def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    opp = [h[1] for h in history]
    last_opp = opp[-1]
    last_me = history[-1][0]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    if opp_d > n * 0.8:
        return 'D'
    window = min(10, n)
    recent = opp[-window:]
    recent_d = recent.count('D')
    if recent_d >= 7:
        return 'D'
    if recent_d == 0:
        return 'C'
    if last_opp == 'D':
        if last_me == 'D':
            if recent_d >= 5 or opp_d > n * 0.6:
                return 'D'
            return 'C'
        else:
            if opp_d > n * 0.3 or recent_d >= 3:
                return 'D'
            return 'C'
    else:
        if last_me == 'D':
            return 'C'
        return 'C'
